import { defineConfig } from "@lingui/cli";
import { formatter } from "@lingui/format-po";

/**
 * Catalogs are gettext `.po`, the format Weblate reads as *bilingual*: with
 * Lingui's generated ids the `msgid` is the English source text itself and the
 * hash is recomputed on parse, so a translator sees "New folder" rather than
 * `MbT6FE`. That is what buys us zero key-naming across the whole app while
 * keeping the catalog readable.
 *
 * `.po` is the source of truth in git; the runtime artifact is generated by
 * `@lingui/vite-plugin` during Vite's transform, so there is no `lingui
 * compile` step and no ICU parser in the bundle.
 */
export default defineConfig({
  sourceLocale: "en",
  locales: ["en", "vi"],
  // Vietnamese has no CLDR parent, so state the fallback: a message missing
  // from vi renders its English source instead of its message id.
  fallbackLocales: { default: "en" },
  catalogs: [
    {
      path: "<rootDir>/src/locales/{locale}/messages",
      // The extension packages hold strings too: one catalog, for now.
      include: [
        "<rootDir>/src",
        "<rootDir>/../../packages/ext-sdk/src",
        "<rootDir>/../../packages/ext-kanban/src",
        "<rootDir>/../../packages/ext-checklist/src",
      ],
      exclude: ["**/node_modules/**", "**/*.test.*", "**/routeTree.gen.ts"],
    },
  ],
  // `#:` source references are the only context a Weblate translator gets.
  format: formatter({
    origins: true,
    lineNumbers: true,
    printPlaceholdersInComments: true,
  }),
  compileNamespace: "es",
  orderBy: "message",
});
